#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    // 1. Container: std::vector storing integers
    std::vector<int> numbers = {7, 2, 9, 1, 5};

    // 2. Algorithm: std::sort operating via Iterators
    // begin() and end() return iterators marking the range [first, last)
    std::sort(numbers.begin(), numbers.end());

    // Iterating through container elements
    std::cout << "Sorted elements:";
    for (auto it = numbers.begin(); it != numbers.end(); ++it) {
        std::cout << " " << *it;
    }
    std::cout << "\n";

    // 3. Algorithm: std::find using iterators
    int target = 5;
    auto found_it = std::find(numbers.begin(), numbers.end(), target);
    if (found_it != numbers.end()) {
        std::cout << "Found target " << *found_it << " at index " 
                  << std::distance(numbers.begin(), found_it) << "\n";
    }

    return 0;
}

#include <iostream>
#include <vector>        // Sequence container
#include <map>           // Ordered associative container
#include <stack>         // Container adapter
#include <bitset>        // Near-container

int main() {
    // 1. First-class Sequence container: std::vector
    std::vector<int> vec = {10, 20, 30};
    vec.push_back(40);
    std::cout << "vector back: " << vec.back() << "\n";

    // 2. First-class Associative container: std::map
    std::map<std::string, int> scores;
    scores["Alice"] = 95;
    scores["Bob"] = 88;
    std::cout << "Alice's score: " << scores["Alice"] << "\n";

    // 3. Container adapter: std::stack (wraps a deque by default)
    std::stack<int> s;
    s.push(1);
    s.push(2);
    std::cout << "stack top: " << s.top() << "\n";

    // 4. Near-container: std::bitset (fixed 8-bit flags)
    std::bitset<8> flags(0b10101010);
    std::cout << "bitset count of 1s: " << flags.count() << "\n";

    return 0;
}
